const ENDPOINTS=["https://pipedapi.adminforge.de","https://pipedapi.kavin.rocks","https://inv.nadeko.net","https://invidious.nerdvpn.de"];
function id(value=""){if(!value.includes("/")&&!value.includes("?"))return value;try{const url=new URL(value,"https://www.youtube.com");return url.searchParams.get("v")||url.pathname.split("/").filter(Boolean).pop()||"";}catch{return value.replace(/^\/watch\?v=/,"").split("&")[0];}}
function normalize(data){const out=[],seen=new Set;const add=(url,type,quality,server)=>{if(typeof url!=="string"||!url.startsWith("http")||seen.has(url))return;seen.add(url);out.push({server,link:url,type,quality:String(quality||"Auto")});};add(data.hlsUrl||data.hls,"m3u8","Auto","YouTube HLS");const sources=[...(Array.isArray(data.videoStreams)?data.videoStreams:[]),...(Array.isArray(data.formatStreams)?data.formatStreams:[]),...(Array.isArray(data.adaptiveFormats)?data.adaptiveFormats:[])];for(const s of sources){const url=s?.url||s?.streamUrl,mime=String(s?.mimeType||s?.mime||s?.type||"").toLowerCase(),container=String(s?.container||s?.format||"").toLowerCase(),video=mime.includes("video")||s?.quality||s?.qualityLabel||s?.resolution;if(!video)continue;const hls=/\.m3u8(?:$|[?&])/i.test(url||{})||mime.includes("mpegurl"),mp4=/mp4|mpeg-4/.test(`${mime} ${container}`)||/\.mp4(?:$|[?&])/i.test(url||{});if(hls)add(url,"m3u8",s.qualityLabel||s.quality||s.resolution,"YouTube HLS");else if(mp4||url)add(url,"mp4",s.qualityLabel||s.quality||s.resolution,"YouTube MP4");}return out;}
async function getStream({link,signal,providerContext}){const videoId=id(link);if(!videoId)return[];for(const endpoint of ENDPOINTS){try{const url=endpoint.includes("/api/v1")?`${endpoint}/videos/${encodeURIComponent(videoId)}`:`${endpoint}/streams/${encodeURIComponent(videoId)}`;const data=(await providerContext.axios.get(url,{signal,timeout:15000})).data||{};const streams=normalize(data);if(streams.length)return streams;}catch{}}return[];}
exports.getStream=getStream;
